 static byte[] Hex(string s){return System.Linq.Enumerable.Range(0,s.Length/2).Select(i=>System.Convert.ToByte(s.Substring(i*2,2),16)).ToArray();}
 static async System.Threading.Tasks.Task<byte[]> Read(System.IO.Stream s,int n,System.Threading.CancellationToken t){var b=new byte[n];int at=0;while(at<n){int got=await s.ReadAsync(b,at,n-at,t);if(got==0)throw new System.Exception("Unexpected EOF");at+=got;}return b;}
 sealed class Echo:ITgSocket {
  byte[] relay;TgCtr receive,send;System.Threading.Tasks.TaskCompletionSource<byte[]> response=new System.Threading.Tasks.TaskCompletionSource<byte[]>(System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously);public byte[] Packet;
  public System.Threading.Tasks.Task Send(byte[] b,System.Threading.CancellationToken t){if(relay==null){relay=b;receive=TgProtocol.RemoteWrite(relay);send=TgProtocol.RemoteRead(relay);}else{Packet=receive.Apply(b);response.TrySetResult(send.Apply(Packet));}return System.Threading.Tasks.Task.CompletedTask;}
  public async System.Threading.Tasks.Task<byte[]> Receive(System.Threading.CancellationToken t){var pending=response;using(t.Register(()=>pending.TrySetCanceled())){var value=await pending.Task;response=new System.Threading.Tasks.TaskCompletionSource<byte[]>(System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously);return value;}}
