 static async System.Threading.Tasks.Task Frame(uint proto,bool longFrame){var key=TgProtocol.Random(16);var echo=new Echo();using(var b=new TelegramBridge(key,(d,m,t)=>System.Threading.Tasks.Task.FromResult<ITgSocket>(echo))){b.Start(0);using(var c=new System.Net.Sockets.TcpClient()){await c.ConnectAsync(System.Net.IPAddress.Loopback,b.Port);var stream=c.GetStream();var raw=TgProtocol.Random(64);System.Buffer.BlockCopy(System.BitConverter.GetBytes(proto),0,raw,56,4);System.Buffer.BlockCopy(System.BitConverter.GetBytes((short)2),0,raw,60,2);var h=(byte[])raw.Clone();using(var tx=new TgCtr(TgProtocol.Hash(TgProtocol.Slice(raw,8,32),key),TgProtocol.Slice(raw,40,16))){var enc=tx.Apply(raw);System.Buffer.BlockCopy(enc,56,h,56,8);await stream.WriteAsync(h,0,h.Length);short dc;uint protocol;Check(TgProtocol.Decode(h,key,out dc,out protocol)&&dc==2&&protocol==proto,"Handshake decode");byte[] header=proto==0xefefefef?(longFrame?new byte[]{0x7f,4,0,0}:new byte[]{4}):System.BitConverter.GetBytes(16);var payload=TgProtocol.Random(16);var packet=header.Concat(payload).ToArray();var encrypted=tx.Apply(packet);await stream.WriteAsync(encrypted,0,encrypted.Length);using(var deadline=new System.Threading.CancellationTokenSource(3000)){var reply=await Read(stream,packet.Length,deadline.Token);using(var rx=TgProtocol.ClientWrite(h,key))Check(rx.Apply(reply).SequenceEqual(packet),"Roundtrip framing "+proto);Check(echo.Packet.SequenceEqual(packet),"Upstream packet");}Check(b.Sessions>=1&&b.Up>0&&b.Down>0,"Counters actual bytes");}}b.Stop();for(int i=0;i<100&&b.Active>0;i++)await System.Threading.Tasks.Task.Delay(10);Check(b.Active==0,"Session cleanup");}}
 static async System.Threading.Tasks.Task Failure(){var key=TgProtocol.Random(16);using(var b=new TelegramBridge(key,(d,m,t)=>{throw new System.IO.IOException("Synthetic upstream failure");})){b.Start(0);using(var c=new System.Net.Sockets.TcpClient()){await c.ConnectAsync(System.Net.IPAddress.Loopback,b.Port);var raw=TgProtocol.Random(64);System.Buffer.BlockCopy(System.BitConverter.GetBytes(0xddddddddU),0,raw,56,4);System.Buffer.BlockCopy(System.BitConverter.GetBytes((short)2),0,raw,60,2);using(var tx=new TgCtr(TgProtocol.Hash(TgProtocol.Slice(raw,8,32),key),TgProtocol.Slice(raw,40,16))){var h=(byte[])raw.Clone();var enc=tx.Apply(raw);System.Buffer.BlockCopy(enc,56,h,56,8);await c.GetStream().WriteAsync(h,0,64);for(int i=0;i<100&&b.Error=="";i++)await System.Threading.Tasks.Task.Delay(10);Check(b.Error.Contains("WebSocket/TLS")&&b.Error.Contains("telegram-diagnostic.txt")&&!b.Error.Contains("1087"),"Upstream failure shown separately from bind failure");}}}}
 static void SavedPort(){var folder=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"veyra-port-"+System.Guid.NewGuid().ToString("N"));System.IO.Directory.CreateDirectory(folder);try{int port;using(var b=new TelegramBridge(TgProtocol.Random(16))){b.StartSaved(folder);port=b.Port;}using(var b=new TelegramBridge(TgProtocol.Random(16))){b.StartSaved(folder);Check(b.Port==port,"Saved endpoint survives restart");}var occupied=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,port);occupied.Start();try{using(var b=new TelegramBridge(TgProtocol.Random(16))){bool failed=false;try{b.StartSaved(folder);}catch(System.Net.Sockets.SocketException){failed=true;}Check(failed&&!b.Running,"Busy saved endpoint never silently changes");}}finally{occupied.Stop();}}finally{System.IO.Directory.Delete(folder,true);}}
 static async System.Threading.Tasks.Task MediaConcurrency(){var key=TgProtocol.Random(16);var all=new System.Collections.Generic.List<System.Net.Sockets.TcpClient>();using(var bridge=new TelegramBridge(key,(d,m,t)=>System.Threading.Tasks.Task.FromResult<ITgSocket>(new Echo()))){bridge.Start(0);try{for(int i=0;i<64;i++){var c=new System.Net.Sockets.TcpClient();all.Add(c);await c.ConnectAsync(System.Net.IPAddress.Loopback,bridge.Port);var stream=c.GetStream();short dc=(short)(i%2==0?203:-203);var raw=TgProtocol.Random(64);System.Buffer.BlockCopy(System.BitConverter.GetBytes(0xddddddddU),0,raw,56,4);System.Buffer.BlockCopy(System.BitConverter.GetBytes(dc),0,raw,60,2);var hello=(byte[])raw.Clone();using(var tx=new TgCtr(TgProtocol.Hash(TgProtocol.Slice(raw,8,32),key),TgProtocol.Slice(raw,40,16))){var enc=tx.Apply(raw);System.Buffer.BlockCopy(enc,56,hello,56,8);await stream.WriteAsync(hello,0,64);using(var rx=TgProtocol.ClientWrite(hello,key))using(var deadline=new System.Threading.CancellationTokenSource(15000)){int n=i==63?4*1024*1024:64;var packet=System.BitConverter.GetBytes(n).Concat(TgProtocol.Random(n)).ToArray();var wire=tx.Apply(packet);var sending=stream.WriteAsync(wire,0,wire.Length,deadline.Token);var returned=await Read(stream,packet.Length,deadline.Token);await sending;Check(rx.Apply(returned).SequenceEqual(packet),"64 concurrent sessions / 4MiB media / DC203 identity");}}}Check(bridge.Sessions==64,"64 accepted sessions");}finally{foreach(var c in all)c.Dispose();}}}
 static async System.Threading.Tasks.Task WireMedia(){var listener=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0);listener.Start();try{using(var tcp=new System.Net.Sockets.TcpClient()){var accept=listener.AcceptTcpClientAsync();await tcp.ConnectAsync(System.Net.IPAddress.Loopback,((System.Net.IPEndPoint)listener.LocalEndpoint).Port);using(var peer=await accept)using(var deadline=new System.Threading.CancellationTokenSource(15000))using(deadline.Token.Register(()=>{tcp.Close();peer.Close();})){var ws=(ITgSocket)System.Activator.CreateInstance(typeof(TelegramTransport),System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic,null,new object[]{tcp,tcp.GetStream()},null);using(ws){var payload=TgProtocol.Random(4*1024*1024);var serving=System.Threading.Tasks.Task.Run(async()=>{var stream=peer.GetStream();var head=await Read(stream,10,deadline.Token);Check(head[0]==0x82&&head[1]==0xff,"Large client WS binary frame");ulong n=0;for(int i=2;i<10;i++)n=(n<<8)|head[i];Check(n==(ulong)payload.Length,"WS 64-bit length");var mask=await Read(stream,4,deadline.Token);var wire=await Read(stream,payload.Length,deadline.Token);for(int i=0;i<wire.Length;i++)wire[i]^=mask[i%4];Check(wire.SequenceEqual(payload),"WS bulk masking exact bytes");
 for(int part=0;part<2;part++){int count=payload.Length/2;var h=new byte[]{(byte)(part==0?2:128),127,0,0,0,0,0,32,0,0};await stream.WriteAsync(h,0,h.Length,deadline.Token);await stream.WriteAsync(payload,part*count,count,deadline.Token);if(part==0){var ping=new byte[]{137,1,42};await stream.WriteAsync(ping,0,ping.Length,deadline.Token);}}
 var pong=await Read(stream,7,deadline.Token);Check(pong[0]==138&&pong[1]==129&&(byte)(pong[6]^pong[2])==42,"WS ping/pong amid media fragments");});await ws.Send(payload,deadline.Token);Check((await ws.Receive(deadline.Token)).SequenceEqual(payload),"Fragmented WS media exact bytes");await serving;}}}}finally{listener.Stop();}}
